if x > 0:
    if x < 10:
        print('Small Positive')
    else:
        print('Large Positive')
else:
    print('Non-positive')

choices.A:
if x > 0:
    if y > 0:
        print('Both positive')
    else:
        print('x positive, y non-positive')
else:
    print('x non-positive')

choices.B:
if x > 0:
else y > 0:
    print('Both positive')
else:
